export type Card = { monster: string; rank?: number };

const SPHINX = "sphinx";
const THREE_TYPES = 3;
const BASE_POINTS = 1;
const POINTS_PER_TYPE_BEYOND_THREE = 2;
const POINTS_WITHIN_THREE_TYPES = 1;

const countDistinctMonsterTypes = (cards: Card[]): number =>
  new Set(cards.map((card) => card.monster)).size;

// "Sphinx — 1 point. 2 per type beyond three, else 1."
// The types a Sphinx sees are those of the other cards in the army: it does
// not count itself, but it does count a second Sphinx.
const pointsForSphinx = (otherCards: Card[]): number => {
  const types = countDistinctMonsterTypes(otherCards);
  return (
    BASE_POINTS +
    (types > THREE_TYPES
      ? POINTS_PER_TYPE_BEYOND_THREE * (types - THREE_TYPES)
      : POINTS_WITHIN_THREE_TYPES)
  );
};

export const scoreArmy = (army: Card[]): number =>
  army.reduce(
    (score, card, index) =>
      card.monster === SPHINX
        ? score + pointsForSphinx(army.filter((_, other) => other !== index))
        : score,
    0,
  );

