// Independent reference: the per-Sphinx definition derived from the spec.
const ref = (army: Card[]): number => {
  let total = 0;
  army.forEach((card, i) => {
    if (card.monster !== "sphinx") return;
    const others = army.filter((_, j) => j !== i);
    const t = new Set(others.map((c) => c.monster)).size;
    total += 1 + (t > 3 ? 2 * (t - 3) : 1);
  });
  return total;
};

const monsters = ["sphinx","undead-warrior","zombie","hydra","cyclops","orthrus","chimera"];
